import { resolveDeployedResources } from '../../utils/blueprints/resolve-deployed-resources.js';
import { CODE_OPERATION_UNCONFIRMED, EXIT_OPERATION_UNCONFIRMED } from '../../utils/exit-codes.js';
import { runCommand } from '../../utils/package-manager.js';
import { styleText } from '../../utils/style-text.js';
import { isAssetResource, } from '../../utils/types.js';
import { processAssets } from './process-assets.js';
import { updateStack } from './stacks.js';
import { waitForOperation } from './wait-for-operation.js';
export async function preDeploy(options) {
    const { resources, stackId, auth, blueprintFileDir, installer, logger } = options;
    const hasAssetResources = resources.some(isAssetResource);
    if (hasAssetResources) {
        const preDeployStackResult = await preDeployStack(options);
        if (!preDeployStackResult.success) {
            return preDeployStackResult;
        }
        /** Look up resources from the back-end and attach the externalId if possible */
        const resolvedResources = await resolveDeployedResources({
            resources,
            stackId,
            auth,
            logger,
        });
        const assetResources = resolvedResources.filter(isAssetResource);
        let processedAssets;
        try {
            processedAssets = await processAssets({
                assetResources,
                auth,
                blueprintFileDir,
                installer,
                logger,
                onProgress: (progress) => options.onAssetEvent?.({ type: 'progress', progress }),
                onResult: (result) => options.onAssetEvent?.({ type: 'result', result }),
            });
        }
        finally {
            options.onAssetEvent?.({ type: 'complete' });
        }
        const failure = processedAssets.find((result) => !result.success);
        if (failure)
            return { success: false, error: failure.error };
        // update resources with processed assets
        for (const asset of processedAssets) {
            const idx = resources.findIndex((r) => r.name === asset.resource.name);
            // ! I think this error message is wrong. we somehow have an extra asset
            if (idx === -1)
                throw new Error('Unable to update resource asset');
            resources[idx] = asset.resource;
        }
    }
    return { success: true };
}
async function preDeployStack(options) {
    const { scopeType, scopeId, stackId, stackName, resources, auth, logger, bin, verbose } = options;
    const spinner = logger.ora('Starting pre-deploy...').start();
    const stackMutation = {
        scopeType,
        scopeId,
        name: stackName,
        preDeploy: true,
        document: { resources },
    };
    const { ok: deployOk, stack, error: deployError, } = await updateStack({ stackId, stackMutation, auth, logger });
    if (!deployOk) {
        spinner.fail(`${styleText('red', 'Failed')} to complete Stack pre-deployment`);
        return {
            success: false,
            error: deployError || 'Failed to complete Stack pre-deployment',
            suggestions: [
                `Run \`${runCommand(bin)} blueprints plan\` to preview changes before deploying.`,
                `Run \`${runCommand(bin)} blueprints doctor\` to check your configuration.`,
            ],
        };
    }
    spinner.stop().clear();
    if (stack.changeCount === 0)
        return { success: true };
    logger(styleText('dim', 'Stack deployment progress:'));
    logger('');
    const outcome = await waitForOperation({
        stackId,
        operationId: stack.operationId,
        auth,
        log: logger,
        bin,
        verbose,
        progressNoun: 'pre-deployment',
    });
    if (outcome.type === 'completed') {
        logger(styleText(['bold', 'green'], 'Stack pre-deployment completed!'));
    }
    else if (outcome.type === 'unconfirmed') {
        return {
            success: false,
            error: `Stack pre-deployment was accepted but completion could not be confirmed${outcome.error ? ` (${outcome.error})` : ''}.`,
            code: CODE_OPERATION_UNCONFIRMED,
            exitCode: EXIT_OPERATION_UNCONFIRMED,
            suggestions: [
                'The pre-deployment may or may not have finished on Sanity servers.',
                `Run \`${runCommand(bin)} blueprints info\` to check status.`,
                `Run \`${runCommand(bin)} blueprints logs --watch\` to keep streaming logs.`,
            ],
        };
    }
    else {
        return {
            success: false,
            error: 'Stack pre-deployment failed',
            suggestions: [
                ...outcome.logHints,
                'Review the pre-deployment output above for error details.',
                `Run \`${runCommand(bin)} blueprints logs --verbose\` for more context.`,
                `Run \`${runCommand(bin)} blueprints plan\` to identify issues with your Blueprint.`,
            ],
        };
    }
    return { success: true };
}
